html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro clock(value) -%}{{ frappe.utils.format_datetime(value, "dd-MM-yyyy HH:mm") if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro person(employee) -%}{{ v(frappe.db.get_value("Employee", employee, "employee_name") if employee else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:g}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro zero(value) -%}{{ "{:g}".format((value or 0) | float) }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
<style>
.lpl-paper { font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #000; line-height: 1.5; }
.lpl-paper p { margin: 0 0 9px; }
.lpl-paper table { width: 100%; border-collapse: collapse; }
.lpl-paper tr { page-break-inside: avoid; }
.lpl-paper .ref { margin: 0 0 18px; }
.lpl-paper .ref td { border: 1px solid #000; padding: 5px 8px; vertical-align: middle; font-size: 11px; }
.lpl-paper .ref .co { text-align: center; font-size: 14px; font-weight: bold; }
.lpl-paper .ref .title { font-size: 12.5px; text-align: center; }
.lpl-paper .rows { margin: 0 0 14px; }
.lpl-paper .rows th, .lpl-paper .rows td { border: 1px solid #000; padding: 4px 7px; text-align: left;
  vertical-align: top; }
.lpl-paper .rows th { font-weight: bold; }
.lpl-paper .line { margin: 0 0 12px; }
.lpl-paper .fill { border-bottom: 1px dotted #000; display: inline-block; min-width: 110px; padding: 0 4px;
  min-height: 16px; vertical-align: bottom; }
.lpl-paper .w0 { min-width: 34px; }
.lpl-paper .w1 { min-width: 70px; }
.lpl-paper .w2 { min-width: 130px; }
.lpl-paper .w3 { min-width: 210px; }
.lpl-paper .w4 { min-width: 330px; }
.lpl-paper .box { border: 1px solid #000; min-height: 44px; padding: 5px 7px; margin: 0 0 14px;
  white-space: pre-wrap; }
.lpl-paper .sign { margin: 26px 0 14px; }
.lpl-paper .sign td { width: 50%; padding: 0 22px 0 0; vertical-align: top; border: none; }
.lpl-paper .sign .name { min-height: 18px; font-weight: bold; }
.lpl-paper .sign .rule { border-top: 1px solid #000; padding-top: 3px; }
.lpl-paper .said { font-style: italic; margin: 2px 0 0; }
.lpl-paper h4 { font-size: 12px; font-weight: bold; margin: 16px 0 9px; }
.lpl-paper .tick { display: inline-block; width: 28px; height: 19px; border: 1px solid #000; text-align: center;
  line-height: 19px; vertical-align: middle; margin: 0 8px 0 0; font-weight: bold; }
.lpl-paper .types td { border: none; padding: 3px 0; vertical-align: middle; }
.lpl-paper .state { font-weight: normal; }
</style>
{%- set surname = frappe.db.get_value("Employee", doc.employee, "last_name") -%}
{%- set first = frappe.db.get_value("Employee", doc.employee, "first_name") -%}
{%- set kind = doc.leave_type or "" -%}
{%- set printed = ["Annual Leave", "Maternity Leave", "Paternity Leave", "Sick Leave", "Sick Leave (Half Pay)",
  "Compassionate Leave", "Leave Without Pay"] -%}
<div class="lpl-paper">
<table class="ref">
<tr><td rowspan="2" style="width:24%">{% if logo %}<img src="{{ logo }}" style="max-height:46px">{% endif %}</td>
<td class="co">LUUKA PLASTICS LIMITED</td>
<td rowspan="2" style="width:30%">Doc Ref. No: LPL/HR/15<br>Initial Issue Date: 24/4/2017<br>Revision Date:<br>
Revision No. 0</td></tr>
<tr><td class="title"><b>LEAVE APPLICATION FORM</b></td></tr>
</table>
<h4>Part 1: To be filled by applicant</h4>
<p class="line">Surname: <span class="fill w2">{{ v(surname or doc.employee_name) }}</span>
First Name: <span class="fill w2">{{ v(first if surname else "") }}</span>
Dept. <span class="fill w2">{{ v(doc.department) }}</span>
Section <span class="fill w1">{{ v(doc.custom_work_section) }}</span></p>
<p class="line">Date of appointment: <span class="fill w2">{{ day(doc.custom_date_of_appointment) }}</span></p>
<p class="line">No. of leave days applied for <span class="fill w1">{{ num(doc.total_leave_days) }}</span>
Leave Start Date <span class="fill w2">{{ day(doc.from_date) }}</span>
Leave End Date <span class="fill w2">{{ day(doc.to_date) }}</span></p>
<p class="line"><b>Type of Leave: (Please tick)</b></p>
<table class="types">
<tr><td style="width:34%">Annual Leave:</td>
<td><span class="tick">{{ "&#10003;" if kind == "Annual Leave" else "" }}</span></td></tr>
<tr><td>Maternity/Paternity Leave:</td>
<td><span class="tick">{{ "&#10003;" if kind in ("Maternity Leave", "Paternity Leave") else "" }}</span>
(Attach Medical Certificate)</td></tr>
<tr><td>Sick Leave:</td>
<td><span class="tick">{{ "&#10003;" if kind in ("Sick Leave", "Sick Leave (Half Pay)") else "" }}</span>
(Attach Medical Certificate)</td></tr>
<tr><td>Compassionate Leave:</td>
<td><span class="tick">{{ "&#10003;" if kind == "Compassionate Leave" else "" }}</span>
(Precise Reason) <span class="fill w3">{% if kind == "Compassionate Leave" %}{{ v(doc.description) }}{% endif %}</span>
</td></tr>
<tr><td>Leave without Pay:</td>
<td><span class="tick">{{ "&#10003;" if kind == "Leave Without Pay" else "" }}</span></td></tr>
{%- if kind and kind not in printed %}
<tr><td>{{ v(kind) }}:</td><td><span class="tick">&#10003;</span></td></tr>
{%- endif %}
<tr><td>Salary Requested in Advance:</td>
<td><span class="tick">{{ "&#10003;" if doc.custom_salary_requested_in_advance else "" }}</span> Yes &nbsp;
<span class="tick">{{ "" if doc.custom_salary_requested_in_advance else "&#10003;" }}</span> No</td></tr>
</table>
<p class="line"><b>Employee's signature</b> <span class="fill w4">&nbsp;</span>
<b>Date</b> <span class="fill w2">{{ day(doc.posting_date) }}</span></p>
<h4>Part 2: To be filled by Human Resource/ Administration Officer</h4>
<p class="line">Dates when last leave was taken: From <span class="fill w1">{{ day(doc.custom_last_leave_from) }}</span>
To <span class="fill w1">{{ day(doc.custom_last_leave_to) }}</span>
No of Days <span class="fill w0">{{ num(doc.custom_last_leave_days) }}</span>
type of leave <span class="fill w1">{{ v(doc.custom_last_leave_type) }}</span></p>
<p class="line">Net Balance of Leave due
<span class="fill w1">{% if doc.custom_balance_before %}{{ num(doc.custom_balance_before) }}{% endif %}</span>
days before the leave</p>
<p class="line">Net Balance of sick leave entitlement
<span class="fill w1">{% if doc.custom_sick_balance_before %}{{ num(doc.custom_sick_balance_before) }}{% endif %}</span>
days before leave</p>
<p class="line">Net Balance of sick leave entitlement
<span class="fill w1">{% if doc.custom_sick_balance_before %}{{ zero(doc.custom_sick_balance_after) }}{% endif %}</span>
days after the leave</p>
<p class="line">Net Balance of leave due
<span class="fill w1">{% if doc.custom_balance_before %}{{ zero(doc.custom_balance_after) }}{% endif %}</span>
days after the leave</p>
<p class="line">Signature (HRO) <span class="fill w3">{{ who(doc.custom_hro_by) }}</span>
Date <span class="fill w2">{{ day(doc.custom_hro_on) }}</span></p>
<h4>Part 3: Approval{% if doc.custom_leave_status %} <span class="state">({{ v(doc.custom_leave_status) }})</span>{% endif %}</h4>
<p class="line">Signed by: Manager in line: Name <span class="fill w3">{{ who(doc.custom_supervisor_by) }}</span>
Sign <span class="fill w1">&nbsp;</span> Date <span class="fill w1">{{ day(doc.custom_supervisor_on) }}</span></p>
<p class="line" style="padding-left:62px">Head of Dept: Name <span class="fill w3">{{ who(doc.custom_hod_by) }}</span>
Sign <span class="fill w1">&nbsp;</span> Date <span class="fill w1">{{ day(doc.custom_hod_on) }}</span></p>
<p class="line">Comments:</p>
<div class="box">{{ v(doc.custom_supervisor_remarks) }}
{{ v(doc.custom_hod_remarks) }}
{{ v(doc.custom_hr_remarks) }}</div>
<p class="line">Approved By: Name <span class="fill w3">{{ who(doc.custom_hr_by) }}</span>
Sign <span class="fill w1">&nbsp;</span> Date <span class="fill w1">{{ day(doc.custom_hr_on) }}</span></p>
<h4>Part 4: Accounts Officer</h4>
<p class="line">Salary Advance/Loan <span class="fill w3">{{ money(doc.custom_advance_amount) }}</span> Ugshs</p>
<p class="line">Signature <span class="fill w3">{{ who(doc.custom_accounts_by) }}</span>
Date <span class="fill w2">{{ day(doc.custom_accounts_on) }}</span></p>
</div>
